public class VaultGameTests {
    private static final BlockPos P=new BlockPos(2,2,2);
    private static ItemVaultBlockEntity vault(GameTestHelper h,BlockPos pos,Direction.Axis axis){h.setBlock(pos,AllBlocks.ITEM_VAULT.defaultBlockState().setValue(ItemVaultBlock.HORIZONTAL_AXIS,axis));return h.getBlockEntity(pos,ItemVaultBlockEntity.class);}
    private static List<ItemVaultBlockEntity> structure(GameTestHelper h,int width,int length,Direction.Axis axis){var list=new ArrayList<ItemVaultBlockEntity>();for(int along=0;along<length;along++)for(int x=0;x<width;x++)for(int y=0;y<width;y++)list.add(vault(h,axis==Direction.Axis.X?P.offset(along,x,y):P.offset(x,y,along),axis));settle(list);return list;}
    private static void settle(List<ItemVaultBlockEntity> list){for(int i=0;i<8;i++)for(var member:list)if(!member.isRemoved())ItemVaultBlockEntity.tick(member.getLevel(),member.getBlockPos(),member.getBlockState(),member);}
    private static long amount(ItemVaultBlockEntity vault){long sum=0;for(var view:vault.storage())sum+=view.getAmount();return sum;}
    private static long insert(ItemVaultBlockEntity vault,ItemStack stack,long count,boolean commit){try(var tx=Transaction.openOuter()){long moved=vault.storage().insert(ItemVariant.of(stack),count,tx);if(commit)tx.commit();return moved;}}
    private static CreativeCrateBlockEntity crate(GameTestHelper h){h.setBlock(P,AllBlocks.CREATIVE_CRATE);return h.getBlockEntity(P,CreativeCrateBlockEntity.class);}
    @GameTest public void multiPlacementExtendsWholeSquareSliceUsingFourItems(GameTestHelper h){var list=structure(h,2,2,Direction.Axis.Z);var support=P.south();var player=h.makeMockPlayer(GameType.SURVIVAL);player.setPos(Vec3.atCenterOf(h.absolutePos(P)).add(0,0,5));player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllBlocks.ITEM_VAULT,4));var pos=h.absolutePos(support);var hit=new BlockHitResult(Vec3.atCenterOf(pos).add(0,0,.5),Direction.SOUTH,pos,false);var result=((ItemVaultItem)AllBlocks.ITEM_VAULT.asItem()).place(new BlockPlaceContext(new UseOnContext(player,InteractionHand.MAIN_HAND,hit)));h.assertTrue(result.consumesAction(),"Initial extension placed");for(int x=0;x<2;x++)for(int y=0;y<2;y++)h.assertTrue(h.getBlockState(P.offset(x,y,2)).is(AllBlocks.ITEM_VAULT),"Entire cross section extended");h.assertTrue(player.getMainHandItem().isEmpty(),"Four blocks consumed exactly");h.succeed();}
    @GameTest public void placementSanitizesControllerMetadataButRetainsStoredItems(GameTestHelper h){var source=vault(h,P,Direction.Axis.X);insert(source,new ItemStack(Items.DIAMOND),7,true);var tag=source.saveWithoutMetadata(h.getLevel().registryAccess());tag.putInt("Size",3);tag.putInt("Length",9);tag.store("Controller",BlockPos.CODEC,new BlockPos(100,100,100));var stack=new ItemStack(AllBlocks.ITEM_VAULT);stack.set(DataComponents.BLOCK_ENTITY_DATA,net.minecraft.world.item.component.TypedEntityData.of(AllBlockEntityTypes.ITEM_VAULT,tag));var target=P.east(3);h.setBlock(target.below(),Blocks.STONE);var player=h.makeMockPlayer(GameType.SURVIVAL);player.setPos(Vec3.atCenterOf(h.absolutePos(target)).add(0,0,2));player.setItemInHand(InteractionHand.MAIN_HAND,stack);var below=h.absolutePos(target.below());var hit=new BlockHitResult(Vec3.atCenterOf(below).add(0,.5,0),Direction.UP,below,false);((ItemVaultItem)AllBlocks.ITEM_VAULT.asItem()).place(new BlockPlaceContext(new UseOnContext(player,InteractionHand.MAIN_HAND,hit)));var placed=h.getBlockEntity(target,ItemVaultBlockEntity.class);h.assertTrue(placed.isController()&&placed.getWidth()==1&&placed.getHeight()==1,"Old structure addresses removed on placement");h.assertValueEqual(placed.inventory.inputs.getFirst().getAmount(),7L,"Owned contents survive placement");h.succeed();}
    @GameTest public void wrenchRotatesOneVaultWithoutDroppingAnyStoredContents(GameTestHelper h){var list=structure(h,1,2,Direction.Axis.X);insert(list.getFirst(),new ItemStack(Items.DIAMOND),7,true);var player=h.makeMockPlayer(GameType.SURVIVAL);player.setPos(Vec3.atCenterOf(h.absolutePos(P)).add(0,0,2));player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.WRENCH));var pos=h.absolutePos(P);var hit=new BlockHitResult(Vec3.atCenterOf(pos).add(0,.5,0),Direction.UP,pos,false);AllItems.WRENCH.useOn(new UseOnContext(player,InteractionHand.MAIN_HAND,hit));h.assertValueEqual(h.getBlockState(P).getValue(ItemVaultBlock.HORIZONTAL_AXIS),Direction.Axis.Z,"Wrench rotates horizontal axis");h.assertValueEqual(amount(list.getFirst()),7L,"Local contents retained");h.assertTrue(h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(pos).inflate(2)).isEmpty(),"Rotation has no item drops");h.succeed();}
    @GameTest public void packagerCanMoveAFullBoxFromVaultToAnotherVaultAtomically(GameTestHelper h){var list=structure(h,1,2,Direction.Axis.X);insert(list.getFirst(),new ItemStack(Items.APPLE),600,true);var packPos=P.south();h.setBlock(packPos,AllBlocks.PACKAGER.defaultBlockState().setValue(PackagerBlock.FACING,Direction.SOUTH));var packager=h.getBlockEntity(packPos,PackagerBlockEntity.class);packager.attemptToSend(null);h.assertValueEqual(PackageItem.getContents(packager.heldBox).stream().mapToInt(ItemStack::getCount).sum(),576,"Nine full stacks boxed");h.assertValueEqual(amount(list.getFirst()),24L,"Unpacked balance retained");var destination=vault(h,P.south(4),Direction.Axis.X);var receive=P.south(5);h.setBlock(receive,AllBlocks.PACKAGER.defaultBlockState().setValue(PackagerBlock.FACING,Direction.SOUTH));var receiver=h.getBlockEntity(receive,PackagerBlockEntity.class);for(int tick=0;tick<20;tick++)PackagerBlockEntity.tick(h.getLevel(),packager.getBlockPos(),packager.getBlockState(),packager);var parcel=ItemVariant.of(packager.heldBox);try(var tx=Transaction.openOuter()){h.assertValueEqual(receiver.inventory.insert(parcel,1,tx),1L,"Destination preview");h.assertValueEqual(packager.inventory.extract(parcel,1,tx),1L,"Source preview");}h.assertValueEqual(amount(destination),0L,"Destination simulation unchanged");h.assertFalse(packager.heldBox.isEmpty(),"Abort retains source ownership");try(var tx=Transaction.openOuter()){h.assertValueEqual(receiver.inventory.insert(parcel,1,tx),1L,"Destination commit");h.assertValueEqual(packager.inventory.extract(parcel,1,tx),1L,"Source commit");tx.commit();}h.assertValueEqual(amount(destination),576L,"Every boxed item delivered");h.assertTrue(packager.heldBox.isEmpty(),"Delivered parcel consumed atomically");h.succeed();}
    @GameTest public void singletonHasTwentySlotsAndAbortedInsertionLeavesNoContents(GameTestHelper h){var vault=vault(h,P,Direction.Axis.X);settle(List.of(vault));h.assertValueEqual(insert(vault,new ItemStack(Items.APPLE),1281,false),1280L,"Twenty 64-item slots");h.assertValueEqual(amount(vault),0L,"Preview never changes contents");h.assertValueEqual(insert(vault,new ItemStack(Items.APPLE),1281,true),1280L,"Exactly singleton capacity");h.assertValueEqual(vault.comparatorOutput(),15,"Full comparator");h.succeed();}
    @GameTest public void oneWideVaultStopsAtThreeBlocksAndDoesNotJoinWrongAxis(GameTestHelper h){var list=structure(h,1,4,Direction.Axis.X);var first=list.getFirst().getControllerBE();h.assertValueEqual(first.getWidth(),1,"One-wide structure");h.assertValueEqual(first.getHeight(),3,"Source length limit three times width");h.assertFalse(list.getLast().getController().equals(first.getController()),"Fourth block separate");var other=vault(h,P.south(),Direction.Axis.Z);settle(List.of(other));h.assertFalse(other.getController().equals(first.getController()),"Perpendicular block not merged");h.succeed();}
    @GameTest public void twoWideVaultCombinesAllTwentySlotsPerComponent(GameTestHelper h){var list=structure(h,2,3,Direction.Axis.X);var master=list.getFirst().getControllerBE();h.assertValueEqual(master.getWidth(),2,"Two-by-two cross-section");h.assertValueEqual(master.getHeight(),3,"Three slices");h.assertTrue(list.stream().allMatch(part->part.getController().equals(master.getBlockPos())),"One controller");h.assertValueEqual(insert(master,new ItemStack(Items.APPLE),20000,true),15360L,"Twelve component inventories combined");h.assertValueEqual(list.getLast().comparatorOutput(),15,"Comparator shared by any member");h.succeed();}
    @GameTest public void largestVaultFormsThreeByThreeByNineOnEitherHorizontalAxis(GameTestHelper h){var list=structure(h,3,9,Direction.Axis.Z);var master=list.getFirst().getControllerBE();h.assertValueEqual(master.getWidth(),3,"Largest cross section");h.assertValueEqual(master.getHeight(),9,"Largest length");h.assertValueEqual(master.memberPositions().size(),81,"Eighty-one blocks");h.assertTrue(list.stream().allMatch(part->part.getBlockState().getValue(ItemVaultBlock.LARGE)),"Large texture state propagated");h.assertValueEqual(insert(master,new ItemStack(Items.APPLE),200000,true),103680L,"Source default capacity for eighty-one blocks");h.succeed();}
    @GameTest public void combinedSlotOrderRetainsInventoryInEachOwningBlock(GameTestHelper h){var list=structure(h,1,3,Direction.Axis.X);insert(list.getLast(),new ItemStack(Items.APPLE),1281,true);h.assertValueEqual(list.getFirst().inventory.inputs.stream().mapToLong(slot->slot.getAmount()).sum(),1280L,"First component fills first");h.assertValueEqual(list.get(1).inventory.inputs.getFirst().getAmount(),1L,"Next slot belongs to next block");h.assertTrue(list.getLast().inventory.inputs.stream().allMatch(slot->slot.isResourceBlank()),"Inserting member does not become owner of all items");h.succeed();}
    @GameTest public void mergeDoesNotMoveOrDuplicateExistingComponentContents(GameTestHelper h){var first=vault(h,P,Direction.Axis.X);insert(first,new ItemStack(Items.APPLE),7,true);var second=vault(h,P.east(),Direction.Axis.X);try(var tx=Transaction.openOuter()){second.getInventoryOfBlock().insert(ItemVariant.of(Items.DIAMOND),9,tx);tx.commit();}settle(List.of(first,second));h.assertValueEqual(amount(first),16L,"Combined total");h.assertTrue(first.inventory.inputs.getFirst().stack().is(Items.APPLE),"Original first inventory retained");h.assertTrue(second.inventory.inputs.getFirst().stack().is(Items.DIAMOND),"Original second inventory retained");h.succeed();}
    @GameTest public void destructionDropsOnlyRemovedBlockContentsAndSurvivorsReform(GameTestHelper h){var list=structure(h,1,3,Direction.Axis.X);for(int i=0;i<list.size();i++)try(var tx=Transaction.openOuter()){list.get(i).getInventoryOfBlock().insert(ItemVariant.of(Items.APPLE),i+3,tx);tx.commit();}h.setBlock(P,Blocks.AIR);settle(list.subList(1,3));h.assertValueEqual(amount(list.get(1)),9L,"Surviving blocks retain four plus five items");h.assertValueEqual(h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(h.absolutePos(P)).inflate(2)).stream().filter(entity->entity.getItem().is(Items.APPLE)).mapToInt(entity->entity.getItem().getCount()).sum(),3,"Only broken component drops three");h.succeed();}
    @GameTest public void removedStorageAndCachedViewsCannotExtractContents(GameTestHelper h){var list=structure(h,1,2,Direction.Axis.X);insert(list.getFirst(),new ItemStack(Items.APPLE),9,true);var storage=list.getFirst().storage();var view=storage.iterator().next();list.getFirst().setRemoved();try(var tx=Transaction.openOuter()){h.assertValueEqual(storage.extract(ItemVariant.of(Items.APPLE),9,tx),0L,"Removed BE storage unavailable");h.assertValueEqual(view.extract(ItemVariant.of(Items.APPLE),9,tx),0L,"Old view unavailable");}list.getFirst().clearRemoved();h.assertTrue(view.isResourceBlank(),"Old view never revives after invalidation");h.assertValueEqual(amount(list.getFirst()),9L,"New lookup sees preserved contents");h.succeed();}
    @GameTest public void splittingInvalidatesHeldViewsAndKeepsLocalItems(GameTestHelper h){var list=structure(h,1,2,Direction.Axis.X);insert(list.getFirst(),new ItemStack(Items.APPLE),7,true);var view=list.getFirst().storage().iterator().next();com.simibubi.create.api.connectivity.ConnectivityHandler.splitMulti(list.getFirst());h.assertTrue(view.isResourceBlank(),"Topology change invalidates held view");h.assertValueEqual(amount(list.getFirst()),7L,"Controller local inventory retained");h.succeed();}
    @GameTest public void stableVersionChangesOnlyForCommittedContentsOrTopology(GameTestHelper h){var list=structure(h,1,2,Direction.Axis.X);var storage=list.getLast().storage();long version=storage.getVersion();h.assertValueEqual(storage.getVersion(),version,"Repeated version queries stable");insert(list.getFirst(),new ItemStack(Items.APPLE),9,false);h.assertValueEqual(storage.getVersion(),version,"Abort leaves version stable");insert(list.getFirst(),new ItemStack(Items.APPLE),9,true);h.assertFalse(storage.getVersion()==version,"Committed insertion changes version from another member");h.succeed();}
    @GameTest public void componentsSurviveCrossBlockTransferAndNativeSave(GameTestHelper h){var vault=vault(h,P,Direction.Axis.Z);var named=new ItemStack(Items.APPLE);named.set(DataComponents.CUSTOM_NAME,Component.literal("Stored"));insert(vault,named,12,true);var tag=vault.saveWithFullMetadata(h.getLevel().registryAccess());var restored=(ItemVaultBlockEntity)BlockEntity.loadStatic(vault.getBlockPos(),vault.getBlockState(),tag,h.getLevel().registryAccess());h.assertTrue(ItemStack.isSameItemSameComponents(restored.inventory.inputs.getFirst().stack(),named),"Named components restored");h.assertValueEqual(restored.inventory.inputs.getFirst().getAmount(),12L,"Local count restored");h.assertFalse(vault.getUpdateTag(h.getLevel().registryAccess()).contains("Inventory"),"Client receives structure data without contents");h.succeed();}
    @GameTest public void vaultIdentifierContainsExactlyComponentBounds(GameTestHelper h){var list=structure(h,2,2,Direction.Axis.Z);var id=list.getLast().getInvId();h.assertTrue(id.contains(new BlockFace(h.absolutePos(P),Direction.UP)),"Origin included");h.assertTrue(id.contains(new BlockFace(h.absolutePos(P.offset(1,1,1)),Direction.NORTH)),"Far component included");h.assertFalse(id.contains(new BlockFace(h.absolutePos(P.east(2)),Direction.WEST)),"Adjacent nonmember excluded");h.assertFalse(id.contains(new BlockFace(h.absolutePos(P.above(2)),Direction.DOWN)),"Block over roof excluded");h.succeed();}
    @GameTest public void doubleChestIdentifierCanonicalizesBothHalves(GameTestHelper h){h.setBlock(P,Blocks.CHEST.defaultBlockState().setValue(ChestBlock.FACING,Direction.NORTH).setValue(ChestBlock.TYPE,ChestType.LEFT));h.setBlock(P.east(),Blocks.CHEST.defaultBlockState().setValue(ChestBlock.FACING,Direction.NORTH).setValue(ChestBlock.TYPE,ChestType.RIGHT));var a=InventoryIdentifier.get(h.getLevel(),new BlockFace(h.absolutePos(P),Direction.UP));var b=InventoryIdentifier.get(h.getLevel(),new BlockFace(h.absolutePos(P.east()),Direction.DOWN));h.assertValueEqual(a,b,"Both halves identify same inventory");h.assertTrue(a.contains(new BlockFace(h.absolutePos(P.east()),Direction.SOUTH)),"Other half any side included");h.succeed();}
    @GameTest public void doubleChestStorageUsesNativeSlotOrderAndRollsBackBothHalves(GameTestHelper h){
        doubleChest(h);var storage=FunnelTransfer.find(h.getLevel(),h.absolutePos(P),Direction.UP);var opposite=FunnelTransfer.find(h.getLevel(),h.absolutePos(P.east()),Direction.DOWN);var apple=ItemVariant.of(Items.APPLE);
        try(var tx=Transaction.openOuter()){h.assertValueEqual(storage.insert(apple,4000,tx),3456L,"Fifty-four native slots");}
        h.assertTrue(views(storage).allMatch(view->view.isResourceBlank()),"Both halves roll back");
        try(var tx=Transaction.openOuter()){h.assertValueEqual(storage.insert(apple,1729,tx),1729L,"Fill one half and one item");tx.commit();}
        var state=h.getBlockState(P);var first=ChestBlock.getBlockType(state)==DoubleBlockCombiner.BlockType.FIRST?P:P.east();var second=first.equals(P)?P.east():P;
        h.assertValueEqual(h.getBlockEntity(first,ChestBlockEntity.class).getItem(26).getCount(),64,"Native first-half slot order");h.assertValueEqual(h.getBlockEntity(second,ChestBlockEntity.class).getItem(0).getCount(),1,"Second half retains its own contents");
        try(var tx=Transaction.openOuter()){h.assertValueEqual(opposite.extract(apple,1729,tx),1729L,"Other side shares all contents");}
        h.assertValueEqual(views(storage).mapToLong(view->view.getAmount()).sum(),1729L,"Aborted extraction retains both halves");h.succeed();
    }
    @GameTest public void doubleChestHeldViewsRejectRemovedAndReplacedOwners(GameTestHelper h){
        doubleChest(h);var owner=h.getBlockEntity(P,ChestBlockEntity.class);owner.setItem(0,new ItemStack(Items.DIAMOND,7));var storage=FunnelTransfer.find(h.getLevel(),h.absolutePos(P),null);var view=views(storage).filter(v->!v.isResourceBlank()).findFirst().orElseThrow();
        h.assertTrue(storage==FunnelTransfer.find(h.getLevel(),h.absolutePos(P),null),"Stable lookup object");h.setBlock(P,Blocks.AIR);h.setBlock(P,Blocks.CHEST);var replacement=h.getBlockEntity(P,ChestBlockEntity.class);replacement.setItem(0,new ItemStack(Items.DIAMOND,9));
        try(var tx=Transaction.openOuter()){h.assertValueEqual(storage.extract(ItemVariant.of(Items.DIAMOND),7,tx),0L,"Removed owner cannot transfer");h.assertValueEqual(view.extract(ItemVariant.of(Items.DIAMOND),7,tx),0L,"Held view cannot access replacement");}
        h.assertValueEqual(replacement.getItem(0).getCount(),9,"Replacement remains unchanged");h.succeed();
    }
    @GameTest public void doubleChestSidesExposeSameUnderlyingSlotsForSharedInventoryDetection(GameTestHelper h){
        doubleChest(h);var a=FunnelTransfer.find(h.getLevel(),h.absolutePos(P),Direction.UP);var b=FunnelTransfer.find(h.getLevel(),h.absolutePos(P.east()),Direction.DOWN);var slots=Collections.newSetFromMap(new IdentityHashMap<Object,Boolean>());for(var view:a)slots.add(view.getUnderlyingView());h.assertValueEqual(slots.size(),54,"Distinct native slots");for(var view:b)h.assertTrue(slots.contains(view.getUnderlyingView()),"Other half exposes same underlying slots");h.succeed();
    }
    private static void doubleChest(GameTestHelper h){h.setBlock(P,Blocks.CHEST.defaultBlockState().setValue(ChestBlock.FACING,Direction.NORTH).setValue(ChestBlock.TYPE,ChestType.LEFT));h.setBlock(P.east(),Blocks.CHEST.defaultBlockState().setValue(ChestBlock.FACING,Direction.NORTH).setValue(ChestBlock.TYPE,ChestType.RIGHT));}
    private static java.util.stream.Stream<net.fabricmc.fabric.api.transfer.v1.storage.StorageView<ItemVariant>> views(net.fabricmc.fabric.api.transfer.v1.storage.Storage<ItemVariant> storage){return java.util.stream.StreamSupport.stream(storage.spliterator(),false);}
    @GameTest public void sidedFurnaceIdentifiersDistinguishInputFuelAndOutput(GameTestHelper h){h.setBlock(P,Blocks.FURNACE);var pos=h.absolutePos(P);var side=InventoryIdentifier.get(h.getLevel(),new BlockFace(pos,Direction.WEST));h.assertTrue(side.contains(new BlockFace(pos,Direction.EAST)),"Shared horizontal fuel access");h.assertFalse(side.contains(new BlockFace(pos,Direction.UP)),"Top input has different slots");h.assertFalse(side.contains(new BlockFace(pos,Direction.DOWN)),"Bottom result access has different slots");h.succeed();}
    @GameTest public void packagersRecognizeSameVaultThroughDifferentComponentFaces(GameTestHelper h){structure(h,1,3,Direction.Axis.X);h.setBlock(P.south(),AllBlocks.PACKAGER.defaultBlockState().setValue(PackagerBlock.FACING,Direction.SOUTH));h.setBlock(P.east(2).north(),AllBlocks.PACKAGER.defaultBlockState().setValue(PackagerBlock.FACING,Direction.NORTH));var first=h.getBlockEntity(P.south(),PackagerBlockEntity.class);var second=h.getBlockEntity(P.east(2).north(),PackagerBlockEntity.class);h.assertTrue(first.isTargetingSameInventory(second.getIdentifiedInventory()),"Shared vault identity prevents mutual requests");h.succeed();}
    @GameTest public void creativeCrateSuppliesFullStacksWithoutDepletionAndVoidsAnyInput(GameTestHelper h){var crate=crate(h);crate.filtering.setFilter(new ItemStack(Items.DIAMOND));try(var tx=Transaction.openOuter()){h.assertValueEqual(crate.inv.extract(ItemVariant.of(Items.DIAMOND),200,tx),64L,"One source stack per extraction");h.assertValueEqual(crate.inv.insert(ItemVariant.of(Items.APPLE),200,tx),200L,"Any incoming variant voided");tx.commit();}h.assertValueEqual(crate.inv.getAmount(),64L,"Supply never depletes");try(var tx=Transaction.openOuter()){h.assertValueEqual(crate.inv.extract(ItemVariant.of(Items.APPLE),64,tx),0L,"Only selected item supplied");}h.succeed();}
    @GameTest public void blankCreativeCrateIsStillAVoidAndSampleKeepsComponents(GameTestHelper h){var crate=crate(h);try(var tx=Transaction.openOuter()){h.assertValueEqual(crate.inv.insert(ItemVariant.of(Items.APPLE),64,tx),64L,"Empty crate accepts void input");tx.commit();}h.assertTrue(crate.inv.isResourceBlank(),"No invented output without sample");var named=new ItemStack(Items.DIAMOND_PICKAXE);named.setDamageValue(12);crate.filtering.setFilter(named);try(var tx=Transaction.openOuter()){h.assertValueEqual(crate.inv.extract(ItemVariant.of(named),64,tx),1L,"Unstackable source item respects maximum");}var tag=crate.saveWithFullMetadata(h.getLevel().registryAccess());var restored=(CreativeCrateBlockEntity)BlockEntity.loadStatic(crate.getBlockPos(),crate.getBlockState(),tag,h.getLevel().registryAccess());h.assertTrue(ItemStack.isSameItemSameComponents(restored.filtering.getFilter(),named),"Supply sample persists");h.succeed();}
    @GameTest public void packagerSeesInfiniteCreativeStockAndBoxesNineStacks(GameTestHelper h){var crate=crate(h);crate.filtering.setFilter(new ItemStack(Items.APPLE));h.setBlock(P.south(),AllBlocks.PACKAGER.defaultBlockState().setValue(PackagerBlock.FACING,Direction.SOUTH));var packager=h.getBlockEntity(P.south(),PackagerBlockEntity.class);h.assertValueEqual(packager.getAvailableItems().getCountOf(new ItemStack(Items.APPLE)),BigItemStack.INF,"Stock marked infinite");packager.attemptToSend(null);h.assertValueEqual(PackageItem.getContents(packager.heldBox).stream().mapToInt(ItemStack::getCount).sum(),576,"Nine source stacks packed");h.assertValueEqual(crate.inv.getAmount(),64L,"Creative stock unchanged");h.succeed();}
    @GameTest public void unpackingIntoCreativeCrateVoidsWholeParcelWithoutChangingSupply(GameTestHelper h){var crate=crate(h);crate.filtering.setFilter(new ItemStack(Items.DIAMOND));h.setBlock(P.south(),AllBlocks.PACKAGER.defaultBlockState().setValue(PackagerBlock.FACING,Direction.SOUTH));var packager=h.getBlockEntity(P.south(),PackagerBlockEntity.class);var box=PackageItem.containing(List.of(new ItemStack(Items.APPLE,12)));h.assertTrue(packager.unwrapBox(box,false),"Native void unpacking handler accepts whole box");h.assertTrue(crate.inv.getResource().equals(ItemVariant.of(Items.DIAMOND)),"Supply sample unchanged by void operation");h.succeed();}
    @GameTest public void creativeCrateSampleInteractionIsTopOnlyAndDoesNotConsumeOrdinaryItem(GameTestHelper h){var crate=crate(h);var player=h.makeMockPlayer(GameType.SURVIVAL);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.APPLE,8));var pos=h.absolutePos(P);var hit=new BlockHitResult(CreativeCrateBlock.FILTER_POSITION.add(Vec3.atLowerCornerOf(pos)),Direction.UP,pos,false);h.assertTrue(FilteringSettings.interact(h.getLevel(),player,InteractionHand.MAIN_HAND,hit).consumesAction(),"Top supply sample installed");h.assertValueEqual(player.getMainHandItem().getCount(),8,"Ordinary sample copied");h.assertTrue(crate.filtering.getFilter().is(Items.APPLE),"Sample drives creative output");h.assertFalse(FilteringSettings.activeSide(crate.getBlockState(),Direction.NORTH),"No side sample slot");h.succeed();}
}
